function fullscreenEvent() {
	if (!document.fullscreenElement) {
		document.documentElement.requestFullscreen();
	} else if (document.exitFullscreen) {
		document.exitFullscreen();
	}
}

function saveLocalSettings() {
	let storage = {
		poster: cnv.poster.show,
		windowColor: cnv.windowColor
	}
	localStorage.setItem("rastr", JSON.stringify(storage));
}

function settingsLoad() {
	let storageData = localStorage.getItem("rastr");
	if (storageData) {
		let data = JSON.parse(storageData);
		if (data?.poster !== undefined) {
			cnv.poster.show = JSON.parse(JSON.stringify(data.poster));
			showPoster.refresh();
		}
		if (data?.windowColor !== undefined) {
			cnv.windowColor = JSON.parse(JSON.stringify(data.windowColor));
			windowColor.refresh();
		}
	}
}

function windowColorSettings() {
	let c = map(cnv.windowColor, 0, 100, 0, 255);
	let col = 'rgb(' + c + ',' + c + ',' + c + ')';
	document.body.style.backgroundColor = col;
}


