// === Tab: main.js ===

function setup() {
	canvas = createCanvas(cnv.width, cnv.height);
	canvas.parent(select('section.sketchCanvas'));
	canvas.id("sketchCanvas");
	pixelDensity(cnv.quality.level);
	noStroke();
	imageMode(CENTER);
	textAlign(CENTER, CENTER);
	noiseSeedUpdate();
	centerCanvas();
	createForm();
	updateFillUI();
	updateStrokeUI();
	updateShapeUI();
	loadPreset(cnv.preset);
	checkExportState();
}

function draw() {
	clear();
	background(cnv.bg.r, cnv.bg.g, cnv.bg.b, cnv.bg.a * 255);

	if (cnv.export.image) {
		gForm.pixelDensity(cnv.density + 1);
		drawGraphics();
		cnv.poster.export ? savePosterGraphics() : saveGraphics();
		cnv.export.image = false;
		gForm.pixelDensity(cnv.quality.level);
	} else {
		drawGraphics();
	}

	if (!cnv.export.loop && cnv.poster.show) posterText();
}

function drawGraphics() {
	gForm.clear();
	gForm.push();
	gForm.noFill();
	gForm.noStroke();
	gForm.translate(gForm.width / 2, gForm.height / 2);
	gForm.scale(cnv.scale);
	gForm.rotate(radians(cnv.rotate));

	var frame = capture.length === 0 ? 1 : capture.frame / (capture.length * capture.rate);
	let speed = (capture.length * capture.rate) * map(motion.speed, 0, 100, 0, 0.01);
	let rotation = map(form.rotate, 0, 360, 0, TWO_PI);
	let flow = map2(motion.flow, 0, 100, 0, 50, 'Quadratic', 0);
	let ampX = map2(motion.x.amp, 0, 100, 0, gForm.width / 4, 'Quadratic', 0);
	let ampY = map2(motion.y.amp, 0, 100, 0, gForm.height / 4, 'Quadratic', 0);
	let xfreqX = map2(motion.x.xfreq, 0, 100, 0, 0.05, 'Quadratic', 0);
	let xfreqY = map2(motion.x.yfreq, 0, 100, 0, 0.05, 'Quadratic', 0);
	let yfreqX = map2(motion.y.xfreq, 0, 100, 0, 0.05, 'Quadratic', 0);
	let yfreqY = map2(motion.y.yfreq, 0, 100, 0, 0.05, 'Quadratic', 0);

	let xsize = form.size.x < 1 ? form.size.base * form.size.x : map(form.size.x, 1, 3, form.size.base * form.size.x, form.size.base * form.size.x * form.quantity / 20);
	let ysize = form.size.y < 1 ? form.size.base * form.size.y : map(form.size.y, 1, 3, form.size.base * form.size.y, form.size.base * form.size.y * form.quantity / 20);
	let charsize = form.size.base * form.size.text;

	let gradFill = [0, 0];
	let gradStroke = [0, 0];
	if (form.fill.type === 'gradient') gradFill = getGradientDirection(form.fill.direction, xsize, ysize);
	if (form.stroke.type === 'gradient') gradStroke = getGradientDirection(form.stroke.direction, xsize, ysize);

	gForm.textAlign(CENTER, CENTER);
	gForm.textStyle(window[form.char.style]);
	gForm.textFont(form.char.font, charsize);
	gForm.strokeWeight(form.stroke.width);

	let count = 0;
	if (form.arrange === 'backward') count = particles.length - 1;

	for (let i = 0; i < particles.length; i++) {
		let j = abs(count - i);
		particles[j].noise(j, frame, speed, flow, ampX, ampY, xfreqX, xfreqY, yfreqX, yfreqY);
		particles[j].shape(j, xsize, ysize, rotation, gradFill[0], gradFill[1], gradStroke[0], gradStroke[1]);
	}

	gForm.pop();
	image(gForm, width / 2, height / 2, width, height);
	frame === 1 ? capture.frame = 0 : capture.frame++;

	if (capture.length === 0 && !cnv.export.loop) noLoop();
}

function noiseSeedUpdate() {
	simplex = new SimplexNoise(alea(motion.seed));
	randomSeed(motion.seed);
	updateRandomArray();
	updateFillArray();
	updateStrokeArray();
}

function updateRandomArray() {
	for (let i = 0; i < particles.length; i++) {
		particles[i].flow.random = getRandomPI();
	}
}

function getCharsSizeForGradient() {
	gForm.push();

	var charsize = form.size.base * form.size.text;
	let style;

	switch (form.char.style) {
		case 'NORMAL':
			style = '';
			break;
		case 'BOLD':
			style = 'bold';
			break;
		case 'ITALIC':
			style = 'italic';
			break;
		case 'BOLDITALIC':
			style = 'italic bold';
			break;
	}

	gForm.drawingContext.font = `${style} ${charsize}px ${form.char.font}`;
	let textsize = gForm.drawingContext.measureText(form.text);
	char.fill = [textsize.actualBoundingBoxLeft + textsize.actualBoundingBoxRight, textsize.actualBoundingBoxAscent + textsize.actualBoundingBoxDescent];
	char.stroke = [textsize.actualBoundingBoxLeft + textsize.actualBoundingBoxRight, textsize.actualBoundingBoxAscent + textsize.actualBoundingBoxDescent];

	char.fill = getGradientDirection(form.fill.direction, char.fill[0], char.fill[1]);
	char.stroke = getGradientDirection(form.stroke.direction, char.stroke[0], char.stroke[1]);

	gForm.pop();
}

function getGradientDirection(direction, xsize, ysize) {
	let gradx, grady;
	switch (direction) {
		case 'horizontal':
			gradx = xsize;
			grady = 0;
			break;
		case 'vertical':
			gradx = 0;
			grady = ysize;
			break;
		case 'diagonal':
			gradx = ysize;
			grady = xsize;
			break;
	}
	return [gradx, grady];
}

function cnvResize() {
	resizeCanvas(cnv.width, cnv.height);
}

function centerCanvas() {
	let x = (windowWidth - width) / 2 - uiSize;
	let y = (windowHeight - height) / 2;
	canvas.position(x, y);
}

function windowResized() {
	centerCanvas();
}


// === Tab: particles.js ===

function createForm() {
	if (gForm !== undefined) gForm.remove();
	gForm = createGraphics(cnv.form.width, cnv.form.height);
	gForm.pixelDensity(cnv.quality.level);
	gForm.rectMode(CENTER);
	gForm.imageMode(CENTER);
	gForm.noStroke();

	if (gText !== undefined) gText.remove();
	gText = createGraphics(cnv.form.width, cnv.form.height);
	gText.pixelDensity(1);
	gText.noStroke();
}

function updateParticles() {
	randomSeed(motion.seed);
	gForm.clear();
	gForm.image(gText, gForm.width / 2, gForm.height / 2, gText.width, gText.height);
	updateParticlesSize();
	particles = [];
	let id = 0;

	for (let i = 0; i < form.quantity; i++) {
		for (let j = 0; j < form.quantity; j++) {
			var x = map(j, 0, form.quantity, -gText.width / 2 + form.size.base / 2, gText.width / 2 + form.size.base / 2);
			var y = map(i, 0, form.quantity, -gText.height / 2 + form.size.base / 2, gText.height / 2 + form.size.base / 2);
			let x1 = map(j, 0, form.quantity, form.size.base / 2, gText.width + form.size.base / 2);
			let y1 = map(i, 0, form.quantity, form.size.base / 2, gText.height + form.size.base / 2);
			var c = gForm.get(x1, y1);

			if (c[3] !== 0) {
				particles.push(new Particle(id, x, y, c, c));
				id++;
			}
		}
	}
	formsArrange();
	getCharsSizeForGradient();
	updateFillArray();
	updateStrokeArray();
}

class Particle {
	constructor(id, x, y, f, s) {
		this.id = id;
		this.x = x;
		this.y = y;
		this.fill = f;
		this.stroke = s;
		this.random = {
			x: 0,
			y: 0
		}
		this.flow = {
			x: 0,
			y: 0,
			random: getRandomPI()
		};
		this.frame = 0;
	}

	noise(i, frame, speed, flow, ampX, ampY, xfreqX, xfreqY, yfreqX, yfreqY) {
		this.random.x = simplex.noise4D(this.x * xfreqX, -1231.2 - this.y * xfreqY, speed * sin(TWO_PI * frame), speed * cos(TWO_PI * frame)) * ampX;
		this.random.y = simplex.noise4D(11221.4 + this.x * yfreqX, 7922.1 + this.y * yfreqY, speed * sin(TWO_PI * frame), speed * cos(TWO_PI * frame)) * ampY;

		this.flow.x = simplex.noise3D(i + this.flow.random * 998.2, speed * sin(TWO_PI * frame), speed * cos(TWO_PI * frame)) * flow;
		this.flow.y = simplex.noise3D(i + this.flow.random * -1123.3, speed * cos(TWO_PI * frame), speed * sin(TWO_PI * frame)) * flow;
	}

	shape(i, xsize, ysize, rotation, fillx, filly, strokex, strokey) {
		gForm.push();
		gForm.translate(this.x * form.dimension.x + this.random.x + this.flow.x, this.y * form.dimension.y + this.random.y + this.flow.y);
		gForm.rotate(rotation);
		switch (form.type) {
			case 'ellipse':
				this.sColor(i, strokex * form.stroke.soft, strokey * form.stroke.soft, strokex, strokey);
				this.fColor(i, fillx * form.fill.soft, filly * form.fill.soft, fillx, filly);
				gForm.ellipse(0, 0, xsize, ysize);
				break;

			case 'rect':
				this.sColor(i, strokex * form.stroke.soft, strokey * form.stroke.soft, strokex, strokey);
				this.fColor(i, fillx * form.fill.soft, filly * form.fill.soft, fillx, filly);
				gForm.rect(0, 0, xsize, ysize);
				break;

			case 'triangle':
				this.sColor(i, strokex * form.stroke.soft, strokey * form.stroke.soft, strokex, strokey);
				this.fColor(i, fillx * form.fill.soft, filly * form.fill.soft, fillx, filly);
				// gForm.triangle(-xsize / 2, ysize / 2, 0, -ysize, xsize / 2, ysize / 2);
				gForm.triangle(-xsize / 2, -ysize / 2, xsize / 2, -ysize / 2, xsize / 2, ysize / 2);
				break;

			case 'text':
				this.sColor(i, char.stroke[0] * form.stroke.soft, char.stroke[1] * form.stroke.soft, char.stroke[0], char.stroke[1]);
				this.fColor(i, char.fill[0] * form.fill.soft, char.fill[1] * form.fill.soft, char.fill[0], char.fill[1]);
				gForm.text(form.text, 0, 0);
				break;
		}
		gForm.pop();
	}

	fColor(i, x, y, xoff, yoff) {
		switch (form.fill.type) {
			case 'none':
				break;

			case 'single':
				gForm.fill(form.fill.one.r, form.fill.one.g, form.fill.one.b, form.fill.one.a * 255);
				break;

			case 'gradient':
				gForm.fill(0);
				let gradient = gForm.drawingContext.createLinearGradient(-x + xoff * form.fill.offset, -y + yoff * form.fill.offset, x + xoff * form.fill.offset, y + yoff * form.fill.offset);
				gradient.addColorStop(0, `rgba(${form.fill.one.r}, ${form.fill.one.g}, ${form.fill.one.b}, ${form.fill.one.a})`);
				// gradient.addColorStop(0.5, `rgba(${form.fill.one.r}, ${form.fill.one.g}, ${form.fill.one.b}, ${form.fill.one.a})`);
				gradient.addColorStop(1, `rgba(${form.fill.two.r}, ${form.fill.two.g}, ${form.fill.two.b}, ${form.fill.two.a})`);
				gForm.drawingContext.fillStyle = gradient;
				break;

			case 'shuffle':
				gForm.fill(fillArray[i][0], fillArray[i][1], fillArray[i][2], fillArray[i][3]);
				break;
		}
	}

	sColor(i, x, y, xoff, yoff) {
		switch (form.stroke.type) {
			case 'none':
				break;

			case 'single':
				gForm.stroke(form.stroke.one.r, form.stroke.one.g, form.stroke.one.b, form.stroke.one.a * 255);
				break;

			case 'gradient':
				gForm.stroke(0);
				var gradient = gForm.drawingContext.createLinearGradient(-x + xoff * form.stroke.offset, -y + yoff * form.stroke.offset, x + xoff * form.stroke.offset, y + yoff * form.stroke.offset);
				gradient.addColorStop(0, `rgba(${form.stroke.one.r}, ${form.stroke.one.g}, ${form.stroke.one.b}, ${form.stroke.one.a})`);
				// gradient.addColorStop(0.5, `rgba(${form.stroke.one.r}, ${form.stroke.one.g}, ${form.stroke.one.b}, ${form.stroke.one.a})`);
				gradient.addColorStop(1, `rgba(${form.stroke.two.r}, ${form.stroke.two.g}, ${form.stroke.two.b}, ${form.stroke.two.a})`);
				gForm.drawingContext.strokeStyle = gradient;
				break;

			case 'shuffle':
				gForm.stroke(strokeArray[i][0], strokeArray[i][1], strokeArray[i][2], strokeArray[i][3]);
				break;
		}
	}
}

function updateParticlesSize() {
	form.size.base = gForm.width / form.quantity;
}

function updateFillArray() {
	randomSeed(motion.seed);
	fillArray = [];
	for (let i = 0; i < particles.length; i++) {
		let f = [];
		let trans = map(i, 0, particles.length, form.fill.one.a, form.fill.two.a);
		var col = color(spectral.mix(
			[form.fill.one.r, form.fill.one.g, form.fill.one.b],
			[form.fill.two.r, form.fill.two.g, form.fill.two.b],
			i / particles.length, spectral.RGB));
		f[0] = col.levels[0];
		f[1] = col.levels[1];
		f[2] = col.levels[2];
		f[3] = trans * 255;

		fillArray[i] = f;
	}
	shuffle(fillArray, true);
}

function updateStrokeArray() {
	randomSeed(motion.seed);
	strokeArray = [];
	for (let i = 0; i < particles.length; i++) {
		var f = [];
		var trans = map(i, 0, particles.length, form.stroke.one.a, form.stroke.two.a);
		var col = color(spectral.mix(
			[form.stroke.one.r, form.stroke.one.g, form.stroke.one.b],
			[form.stroke.two.r, form.stroke.two.g, form.stroke.two.b],
			i / particles.length, spectral.RGB));
		f[0] = col.levels[0];
		f[1] = col.levels[1];
		f[2] = col.levels[2];
		f[3] = trans * 255;

		strokeArray[i] = f;
	}
	shuffle(strokeArray, true);
}

function getRandomPI() {
	return random(-PI, PI);
}

function formsArrange() {
	if (form.arrange === 'random') {
		shuffle(particles, true);
	} else {
		particles.sort(forwardSort());
	}
}

function forwardSort() {
	return function(elem1, elem2) {
		if (elem1.id < elem2.id) {
			return -1;
		} else if (elem1.id > elem2.id) {
			return 1;
		} else {
			return 0;
		}
	};
}


// === Tab: text.js ===

function promptFunction() {
	let font;
	let fontSize = map2(prompt.size, 1, 100, (gForm.width + gForm.height) * 0.03, gForm.width + gForm.height, 'Cubic', 0);
	if (prompt.font === 'googleFont') {
		font = prompt.google;
	} else {
		font = prompt.font;
	}

	document.fonts.load(`${fontSize}px ${font}`).then(
		() => {
			if (form.char.use === 'inherit') form.char.font = font;
			gText.clear();
			gText.push();
			gText.translate(prompt.offset.x * fontSize, prompt.offset.y * fontSize);
			gText.textStyle(window[prompt.style]);
			gText.textAlign(window[prompt.align], CENTER);
			gText.textSize(fontSize);
			gText.textLeading(fontSize * prompt.leading);
			gText.drawingContext.letterSpacing = `${prompt.spacing}px`;
			gText.textFont(font);
			let text = checkTextReplace(prompt.text, "/n", "\n");
			gText.text(text, 0, -fontSize / 2, gText.width + prompt.spacing / 2, gText.height + fontSize);
			gText.pop();

			updateParticles();
			if (!isLooping()) loop();
		},
		(err) => {
			console.error(err);
		},
	);
}

function checkTextReplace(s, char, char2) {
	if (s.search(char) !== -1) s = s.replaceAll(char, char2);
	if (s === "") s = "empty";
	return s;
}

let googleFontLoader = function(param) {
	var text = checkTextReplace(param, " ", "+");
	let link = document.createElement('link');
	link.href = 'https://fonts.googleapis.com/css?family=' + text;
	link.rel = 'stylesheet';
	link.type = 'text/css';
	document.head.appendChild(link);
	cnv.poster.font = prompt.google;
	let cssnum = document.styleSheets.length;
	let ti = setInterval(function() {
		if (document.styleSheets.length > cssnum) {
			promptFunction();
			clearInterval(ti);
		}
	}, 10);
};

function loadLocalFont() {
	const input = document.createElement('input');
	input.type = 'file';
	input.accept = 'font/*, .woff, .woff2';
	input.onchange = (e) => {
		const file = e.target.files[0];
		const last = file.name.lastIndexOf('.');
		cnv.poster.font = file.name.slice(0, last);
		const fileReader = new FileReader();
		fileReader.readAsDataURL(file);
		fileReader.onloadend = function() {
			let content = fileReader.result;
			let newStyle = document.createElement('style');
			newStyle.appendChild(document.createTextNode(`@font-face {font-family: userFont;  src: url('${content}');}`));
			document.head.appendChild(newStyle);
			promptFunction();
		}
	};
	input.click();
}

function posterText() {	
	var font = prompt.font;
	if (prompt.font === 'googleFont') font = prompt.google;

	push();	
	textFont(font);
	textSize(cnv.poster.size);
	fill(map(cnv.bg.r, 0, 255, 255, 0), map(cnv.bg.g, 0, 255, 255, 0), map(cnv.bg.b, 0, 255, 255, 0));

	push();
	translate(cnv.poster.offset, cnv.poster.offset);	
	textAlign(LEFT, TOP);
	text("RASTR", 0, 0);
	translate(0, cnv.poster.size + cnv.poster.leading);
	text(`VERSION ${cnv.poster.version}`, 0, 0);
	// text('FPS: ' + round(frameRate()), 0, 0);
	pop();

	push();
	translate(width - cnv.poster.offset, cnv.poster.offset);	
	textAlign(RIGHT, TOP);
	text("→ 2024", 0, 0);
	translate(0, cnv.poster.size + cnv.poster.leading);
	text("ANTLII.WORK", 0, 0);
	pop();

	push();
	translate(cnv.poster.offset, height - cnv.poster.offset);	
	textAlign(LEFT, BASELINE);
	text("TEXT PROMPTS INTO GRAPHICS & MOTION ART", 0, 0);
	translate(0, -cnv.poster.size - cnv.poster.leading);
	text("CUSTOM P5.JS TOOL FOR RASTERIZING", 0, 0);
	pop();

	push();
	translate(width - cnv.poster.offset, height - cnv.poster.offset);	
	textAlign(RIGHT, BASELINE);
	// text("ANTLII.WORK/RASTR-TOOL", 0, 0);
	text(`${cnv.poster.font.toUpperCase()} : FONT`, 0, 0);
	translate(0, -cnv.poster.size - cnv.poster.leading);
	text(`${particles.length} : PARTICLES`, 0, 0);	
	translate(0, -cnv.poster.size - cnv.poster.leading);
	text(`${capture.frame} : FRAMES`, 0, 0);	
	pop();

	pop();	
}


// === Tab: capture.js ===

function baseFilename() {
	return "rastr-" + year() + '-' + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second();
}

function checkExportState() {
	const state = p5capture.state === 'capturing' ? `${capture.frame} of ${capture.length * capture.rate} frames` : p5capture.state;
	const clip = capture.length === 0 ? 'static' : `${capture.length} seconds`;
	capture.status = `Graphics Size: ${floor(width * cnv.density)} x ${floor(height * cnv.density)} px\nVideo Length: ${clip}\nState: ${state}`;
}

function savePosterGraphics(){
	posterText();
	save(`${baseFilename()}.png`);
}

function saveGraphics() {
	let s = createGraphics(width, height);
	s.pixelDensity(cnv.density);
	s.background(cnv.bg.r, cnv.bg.g, cnv.bg.b, cnv.bg.a * 255);
	s.image(gForm, 0, 0, width, height);
	s.save(`${baseFilename()}.png`);
	s.remove();
}

function exportLoop() {
	cnv.export.loop = true;
	capture.frame = 0;

	exportAbortButton.hidden = false;
	exportGraphicImage.hidden = true;
	exportVideoAnimation.hidden = true;

	pixelDensity(cnv.density);
	gForm.pixelDensity(cnv.density + 1);

	p5capture.start({
		format: capture.type,
		baseFilename: baseFilename,
		width: floor(width * cnv.density),
		height: floor(height * cnv.density),
		quality: capture.quality / 100,
		framerate: capture.rate,
		duration: capture.length * capture.rate,
		// autoSaveDuration: floor(600 / capture.density),
	});
	exportInterval = setInterval(checkExportProcess, 50);
}

function afterExport() {
	clearInterval(exportInterval);

	pixelDensity(cnv.quality.level);
	gForm.pixelDensity(cnv.quality.level);

	cnv.export.loop = false;
	exportAbortButton.hidden = true;
	exportGraphicImage.hidden = false;
	exportVideoAnimation.hidden = false;
}

function stopExport() {
	p5capture.stop();
}

function checkExportProcess() {
	checkExportState();
	if (p5capture.state === 'idle') afterExport();
}


