function loadPreset(data) {
	if (data === 'Random Values') {
		randomParams();
	} else if (data === 'User Preset') {
		loadCashedPreset();
	} else {
		fetch(data)
			.then(response => response.json())
			.then(json => {
				preset = json;
				presetChange();
			});
	}
}

function importPreset() {
	let element = document.createElement('div');
	element.innerHTML = '<input type="file" accept="application/json">';
	let fileInput = element.firstChild;

	fileInput.addEventListener('change', function() {
		var file = fileInput.files[0];
		let reader = new FileReader(file);
		reader.onload = async (e) => {
			let aaa = e.target.result;
			preset = await JSON.parse(aaa);
			localStorage.setItem('rastrUserPreset', JSON.stringify(preset));
			cnv.preset = 'User Preset';
			presetChange();
		}
		reader.readAsText(file);
	});
	fileInput.click();
}

function exportPreset() {
	const exportData = saveParameters();

	const a = document.createElement("a");
	a.href = URL.createObjectURL(new Blob([JSON.stringify(exportData, null, 2)], {
		type: "application/json"
	}));
	a.setAttribute("download", "rastr-preset-" + year() + '-' + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + '.json');

	document.body.appendChild(a);
	a.click();
	document.body.removeChild(a);
}

