		if (preset?.capture?.length !== undefined) {
			capture.length = JSON.parse(JSON.stringify(preset.capture.length));
		} else {
			skippedParameter("Capture (Length)");
		}

		pane.refresh();
		promptFunction();
	}
	isLoaded = true;
}

